    function quickMenu(section='cities',level='all',selected=null){travelError=null;travelSection=section;travelLevel=level;travelSelection=selected;travelTab='quick';movementMenu();}
    function movementMenu(){
        popupBase('Перемещение',{back:true});popup.classList.add('atlas-movement-panel');
        const blocked=state.quickTravel?.blocked;
        if(travelError)popup.insertAdjacentHTML('beforeend','<p role="alert">'+esc(travelError)+'</p>');
        popup.insertAdjacentHTML('beforeend',movementHtml(state,{tab:travelTab,section:travelSection,level:travelLevel,selected:travelSelection,blocked:blocked?(errors[blocked]||'Телепорт сейчас недоступен.'):null,busy}));
        if(state.player.worldPoint&&state.player.mode==='road'){
            popup.insertAdjacentHTML('beforeend','<button type="button" class="ui-button" data-native-stop>Остановиться</button>');
            popup.querySelector('[data-native-stop]').onclick=()=>act({action:'native_stop'});
        }
        const walk=travelSelection?.kind==='location'&&state.nativeWalk?.[travelSelection.id];
        if(walk){
            popup.querySelector('.atlas-travel-confirm')?.insertAdjacentHTML('beforeend',`<button type="button" class="ui-button" data-native-walk ${busy||blocked||!walk.enabled||walk.exitRequired?'disabled':''}>${walk.exitRequired?'Подойдите к выходу из локации':walk.viaCity?'Пешком через '+esc(walk.viaCity):'Дойти пешком'}</button>`);
            popup.querySelector('[data-native-walk]')?.addEventListener('click',()=>act({action:'walk_location',location:travelSelection.id}));
        }
        if(travelSelection?.kind==='city'&&state.player.mode==='native'&&state.nativeWalkCities?.includes(travelSelection.id)){
            popup.querySelector('.atlas-travel-confirm')?.insertAdjacentHTML('beforeend','<button type="button" class="ui-button" data-native-city>Дойти пешком</button>');
            popup.querySelector('[data-native-city]')?.addEventListener('click',()=>act({action:'native_walk_city',city:travelSelection.id}));
        }
        popup.querySelectorAll('[data-movement-tab]').forEach(b=>b.onclick=()=>{travelTab=b.dataset.movementTab;movementMenu();});
        popup.querySelector('[data-travel-section]')?.addEventListener('change',e=>{travelSection=e.target.value;travelSelection=null;movementMenu();});
        popup.querySelector('[data-travel-level]')?.addEventListener('change',e=>{travelLevel=e.target.value;travelSelection=null;movementMenu();});
        popup.querySelectorAll('[data-quick-go]').forEach(b=>b.onclick=()=>{const q=quickTravelDestinations(state,travelSection,travelLevel)[Number(b.dataset.quickGo)];travelSelection=q&&{kind:q.kind,id:q.id};movementMenu();popup.querySelector('.active[data-quick-go]')?.focus();});
        popup.querySelector('[data-quick-confirm]')?.addEventListener('click',()=>{const q=quickTravelDestinations(state,travelSection,travelLevel).find(q=>q.kind===travelSelection?.kind&&q.id===travelSelection?.id);if(!q||busy)return;popup.querySelectorAll('button').forEach(b=>b.disabled=true);confirmTravel(q).finally(()=>{if(!popup.hidden)movementMenu();});});
        popup.querySelector('[data-escape]')?.addEventListener('click',()=>{popup.hidden=true;act({action:'escape'});});
        popup.querySelector('[data-leave]')?.addEventListener('click',()=>{popup.hidden=true;act({action:state.player.mode==='hall'?'hall_leave':'walk_exit',holding:state.player.holding});});
        enhanceSelects(popup);
    }
    async function confirmTravel(q){try{if(q.kind==='boss'){if(busy)return;busy=true;const {openBossGame}=await import('./boss.js');await openBossGame({...options,initialBoss:q.id});close();return;}const next=await act({action:'quick_travel',[q.kind]:q.id});if(next&&(q.kind==='quest'||q.kind==='location')){const {openHuntGame}=await import('./hunt.js');await openHuntGame(options);close();}}catch(e){const reasons=q.kind==='boss'?(await import('./boss.js')).EPIC_ENTRY_REASONS:errors;travelError=errors[e.payload?.reason]||reasons[e.payload?.reason]||e.message;status.textContent=travelError;popup.insertAdjacentHTML('beforeend','<p role="alert">'+esc(status.textContent)+'</p>');}finally{if(q.kind==='boss')busy=false;}}
    function popupBase(title,{back=false,rules}={}){popup.classList.remove('atlas-movement-panel');popup.hidden=false;popup.innerHTML=dialogHeading(title,{id:'atlas-popup-title',back,rules});popup.querySelector('[data-dismiss]').onclick=()=>popup.hidden=true;popup.querySelector('[data-back]')?.addEventListener('click',()=>popup.hidden=true);}
    function exitPopup(){popupBase('Выход из владения');popup.insertAdjacentHTML('beforeend','<button class="ui-button" data-door-approach>Подойти к выходу</button><button class="ui-button primary" data-door-leave>Выйти</button>');popup.querySelector('[data-door-approach]').onclick=()=>{act({action:state.player.mode==='hall'?'hall_move':state.player.mode==='siege'?'siege_move':'move',holding:state.player.holding,point:{x:.5,y:state.player.mode==='hall'?.9:.95}});popup.hidden=true;};popup.querySelector('[data-door-leave]').onclick=async()=>{if((await act({action:state.player.mode==='hall'?'hall_leave':'walk_exit',holding:state.player.holding}))?.ok)popup.hidden=true;};}
    function passagePopup(){const courtyard=state.hall?.room==='courtyard';popupBase(courtyard?'Внутрь зала':'Во двор');popup.insertAdjacentHTML('beforeend','<button class="ui-button" data-passage-walk>Подойти к двери</button><button class="ui-button primary" data-passage-go>Пройти</button>');popup.querySelector('[data-passage-walk]').onclick=()=>{act({action:'hall_move',holding:state.player.holding,point:{x:.5,y:courtyard?.1:.9}});popup.hidden=true;};popup.querySelector('[data-passage-go]').onclick=async()=>{if((await act({action:'hall_room',holding:state.player.holding}))?.ok)popup.hidden=true;};}
    function developmentPopup(){const d=state.hall?.development;if(!d)return;popupBase('Развитие зала');popup.insertAdjacentHTML('beforeend',hallLocationPreviewHtml(null,{level:d.level,room:'interior'})+'<p>Уровень '+d.level+' / '+d.maxLevel+'</p>'+(d.next?'<p>Слава: '+fmt(d.glory)+' / '+fmt(d.next.glory)+' · Адена из казны: '+fmt(d.next.gold)+'</p><button class="ui-button primary" data-room-upgrade '+(!state.hall.canManage||!d.next.canUpgrade?'disabled':'')+'>Развить до '+d.next.level+' ур.</button>':'<p>Зал полностью развит.</p>'));popup.querySelector('[data-room-upgrade]')?.addEventListener('click',async()=>{if((await act({action:'hall_upgrade',holding:state.player.holding}))?.ok)developmentPopup();});}
    function interiorObjects(){const h=state.holdings.find(h=>h.id===state.player.holding);popupBase(h?.name||'Владение',{rules:h?.contest?hallConquestRules(h.contest):undefined});const nodes=state.player.mode==='hall'?state.hall?.npcs||[]:state.player.mode==='siege'?h?.siege?.objectives||[]:[];popup.insertAdjacentHTML('beforeend',nodes.map((n,i)=>'<button class="ui-button" data-room-node="'+i+'">'+esc(n.name)+(n.hp!==undefined?' · '+Math.ceil(n.hp/n.maxHp*100)+'%':'')+'</button>').join('')+(state.player.mode==='hall'?'<button class="ui-button" data-room-development>Развитие зала · '+(state.hall?.level||1)+' ур.</button>':'')+(state.player.mode==='hall'&&h?.conquerable?'<button class="ui-button" data-room-passage>'+(state.hall?.room==='courtyard'?'Внутрь зала':'Во двор')+'</button>':'')+(state.player.mode==='hall'&&h?.conquerable&&state.hall?.room!=='courtyard'?'':'<button class="ui-button" data-room-exit>Выход</button>'));popup.querySelectorAll('[data-room-node]').forEach(b=>b.onclick=()=>openMarker({kind:state.player.mode==='hall'?'hallnpc':'objective',data:nodes[Number(b.dataset.roomNode)]}));popup.querySelector('[data-room-exit]')?.addEventListener('click',exitPopup);popup.querySelector('[data-room-passage]')?.addEventListener('click',passagePopup);popup.querySelector('[data-room-development]')?.addEventListener('click',developmentPopup);}
    function bindConquestActions(holding,target){popup.querySelectorAll('[data-conquest-action]').forEach(b=>b.onclick=async()=>{const result=await act({action:b.dataset.conquestAction,holding,defenderId:popup.querySelector('[data-conquest-defender]')?.value,payment:popup.querySelector('[data-conquest-payment]')?.value});if(!result?.ok)return;if(b.dataset.conquestAction==='siege_enter'){popup.hidden=true;return;}const h=state.holdings.find(h=>h.id===holding);if(target)conquestObjective(h.contest.objectives.find(n=>n.id===target)||{id:target,name:'Цель',hp:0,maxHp:1});else{popupBase(h.name);holdingPopup(h);}});}
    function lettersPopup(id){const h=state.holdings.find(h=>h.id===id),c=h.contest,letters=Object.entries(c.letterIds).filter(([,item])=>c.bag[item]>0),peers=(h.siege.players||[]).filter(p=>p.userId!==String(state.player.userId)&&p.clanId===c.mine?.clanId&&Math.hypot(p.x-state.player.x,p.y-state.player.y)*2000<=180);popupBase('Передать буквы');if(!letters.length||!peers.length){popup.insertAdjacentHTML('beforeend','<p>Соклановец должен подойти ближе. Передавать можно только собранные буквы.</p>');return;}popup.insertAdjacentHTML('beforeend','<label>Буква<select data-letter>'+letters.map(([letter,item])=>'<option value="'+item+'">'+esc(letter)+' · '+fmt(c.bag[item])+'</option>').join('')+'</select></label><label>Кому<select data-letter-peer>'+peers.map(p=>'<option value="'+esc(p.userId)+'">'+esc(p.name||'Соклановец')+'</option>').join('')+'</select></label><div data-letter-quantity></div><button class="ui-button primary" data-letter-send>Передать</button>');const quantity=popup.querySelector('[data-letter-quantity]'),input=popup.querySelector('[data-letter]');const reset=()=>{quantity.innerHTML=quantityControlHtml({max:c.bag[input.value]});bindQuantityControl(quantity,{max:c.bag[input.value]});};reset();input.onchange=reset;popup.querySelector('[data-letter-send]').onclick=async()=>{if((await act({action:'siege_trade_letter',holding:id,item:Number(input.value),userId:popup.querySelector('[data-letter-peer]').value,amount:Number(quantity.querySelector('[data-quantity-value]').value)}))?.ok)popup.hidden=true;};enhanceSelects(popup);}
    function conquestObjective(node){const h=state.holdings.find(h=>h.id===state.player.holding),c=h.contest;popupBase(node.name,{rules:hallConquestRules(c)});popup.insertAdjacentHTML('beforeend',hallObjectiveHtml(node,c,state.conquestSkills||[]));popup.querySelector('[data-objective-approach]').onclick=()=>{act({action:'siege_move',holding:h.id,point:{x:node.x,y:node.y}});popup.hidden=true;};const attack=async(skillIndex)=>{const result=await act({action:'siege_attack',holding:h.id,target:node.id,...(skillIndex===undefined?{}:{skillIndex})});if(result?.ok){const next=state.holdings.find(r=>r.id===h.id)?.contest?.objectives.find(n=>n.id===node.id);if(next)conquestObjective(next);else interiorObjects();}};popup.querySelector('[data-conquest-attack]')?.addEventListener('click',()=>attack());popup.querySelectorAll('[data-conquest-skill]').forEach(b=>b.onclick=()=>attack(Number(b.dataset.conquestSkill)));popup.querySelectorAll('[data-conquest-item]').forEach(b=>b.onclick=async()=>{if((await act({action:'siege_use_item',holding:h.id,item:Number(b.dataset.conquestItem)}))?.ok){const next=state.holdings.find(r=>r.id===h.id)?.contest?.objectives.find(n=>n.id===node.id);if(next)conquestObjective(next);else interiorObjects();}});popup.querySelector('[data-conquest-trade]')?.addEventListener('click',()=>lettersPopup(h.id));bindConquestActions(h.id,node.id);}
    function holdingPopup(d){if(d.kind==='hall'){popupBase(d.contest?.title||d.name,{rules:d.contest?hallConquestRules(d.contest):undefined});popup.insertAdjacentHTML('beforeend',hallLocationPreviewHtml(d,{level:state.hall?.level||1}));bindScenePreviews(popup);}popup.insertAdjacentHTML('beforeend',`<p>${esc({castle:'Замок',fort:'Форт',hall:'Клан-холл'}[d.kind])} · ${esc(d.owner?.name||'Свободно')}</p><button class="ui-button" data-route ${!d.entry?'disabled':''}>Идти ко входу</button>${!d.entry?'<p>Координаты входа пока не добавлены.</p>':''}<button class="ui-button primary" data-enter ${!d.canEnter||!d.entry?'disabled':''}>Войти${d.kind==='hall'?' в клан-холл':''}</button>${d.conquerable&&!d.contest?'<button class="ui-button" data-register>Зарегистрировать клан</button><button class="ui-button" data-defend>Защищать владение</button><button class="ui-button" data-siege>Войти на осаду</button>':''}${d.siege?`<p>Начало: ${new Date(d.siege.startsAt).toLocaleString('ru')}<br>Конец: ${new Date(d.siege.endsAt).toLocaleString('ru')}</p>`:''}`);popup.querySelector('[data-route]').onclick=()=>act({action:'holding_travel',holding:d.id});popup.querySelector('[data-enter]').onclick=async()=>{if((await act({action:d.kind==='hall'?'hall_enter':'holding_enter',holding:d.id}))?.ok)popup.hidden=true;};popup.querySelector('[data-register]')?.addEventListener('click',()=>act({action:'siege_register',holding:d.id}));popup.querySelector('[data-defend]')?.addEventListener('click',()=>act({action:'siege_register',holding:d.id,side:'defender'}));popup.querySelector('[data-siege]')?.addEventListener('click',async()=>{if((await act({action:'siege_enter',holding:d.id}))?.ok)popup.hidden=true;});if(d.contest){popup.insertAdjacentHTML('beforeend',hallContestHtml(d.contest));bindConquestActions(d.id);enhanceSelects(popup);}}
