    function hallPopup(d){popup.insertAdjacentHTML('beforeend',`<p>${esc(d.role)}</p><button data-approach>Подойти</button>`);popup.querySelector('[data-approach]').onclick=()=>{act({action:'hall_move',holding:state.player.holding,point:{x:d.x,y:d.y}});popup.hidden=true;};if(d.id==='buffer')popup.insertAdjacentHTML('beforeend','<button data-hall-action="hall_buff">Баффы · 5 000 адены</button>');if(d.id==='shop')popup.insertAdjacentHTML('beforeend','<button data-hall-action="hall_scroll">Свиток · 500 адены</button>');if(d.id==='teleport')popup.insertAdjacentHTML('beforeend',(state.hall?.teleports||[]).map(l=>`<button data-hall-tp="${esc(l.id)}">${esc(l.name)} · ${fmt(state.hall.price)}</button>`).join(''));popup.querySelectorAll('[data-hall-action]').forEach(b=>b.onclick=()=>act({action:b.dataset.hallAction,holding:state.player.holding,npc:d.id}));popup.querySelectorAll('[data-hall-tp]').forEach(b=>b.onclick=()=>{act({action:'hall_teleport',holding:state.player.holding,npc:d.id,location:b.dataset.hallTp});popup.hidden=true;});}
    canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};});
    canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>6)drag.moved=true;if(drag.moved){pan.x+=dx;pan.y+=dy;draw();}drag.x=e.clientX;drag.y=e.clientY;});
    canvas.addEventListener('pointerup',e=>{const previous=drag;drag=null;if(!previous||previous.moved)return;const rect=canvas.getBoundingClientRect(),p={x:e.clientX-rect.left,y:e.clientY-rect.top};const marker=markers.filter(m=>Math.hypot(m.x-p.x,m.y-p.y)<m.r).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(marker){openMarker(marker);return;}if(mode==='interior'&&['hall','siege','stronghold'].includes(state.player.mode)){const a=state.player.mode==='hall'?'hall_move':state.player.mode==='siege'?'siege_move':'move';act({action:a,holding:state.player.holding,point:isoPick(p,{width:canvas.clientWidth,height:canvas.clientHeight},{...pan,zoom})});return;}if(!view)return;const world=unproject(p);if(mode==='city'&&state.player.worldPoint){act({action:'native_move',point:world});return;}if(mode==='city'&&region===state.player.city){act({action:'move',point:{x:.5+(world.x-(state.player.entryOrigin||view.city).x)/(state.player.areaSize||cityScale(view.city)),y:.5+(world.y-(state.player.entryOrigin||view.city).y)/(state.player.areaSize||cityScale(view.city))}});return;}const l=state.locations.find(l=>inside(world,l.polygon));if(l){openMarker({kind:'location',data:l});return;}const r=state.regions.find(r=>inside(world,r.polygon));if(r){region=r.id;select.value=region;mode='region';pan={x:0,y:0};zoom=1;draw();}});
    canvas.addEventListener('pointercancel',()=>{drag=null;});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.5,Math.min(6,zoom*(e.deltaY<0?1.15:1/1.15)));draw();},{passive:false});
    root.querySelector('[data-city-view]').onclick=()=>{const city=state.cities.find(c=>c.id===region);if(!city)return;popup.classList.remove('atlas-movement-panel');popup.hidden=false;popup.innerHTML=dialogHeading(city.name,{id:'atlas-popup-title'})+scenePreviewHtml(city.id);bindScenePreviews(popup);popup.querySelector('[data-dismiss]').onclick=()=>popup.hidden=true;};
    select.onchange=()=>{region=select.value;pan={x:0,y:0};zoom=1;draw();};root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;pan={x:0,y:0};zoom=1;if(mode==='city'&&region===state.player.city&&['city','entrance'].includes(state.player.mode))focusMe();draw();});layerSelect.onchange=()=>{const previous=layer;layer=layerSelect.value;if(layer==='gracia'&&previous!=='gracia')graciaReturnRegion=region;if(previous==='gracia'&&layer!=='gracia'&&graciaReturnRegion){region=graciaReturnRegion;select.value=region;graciaReturnRegion=null;}mode='region';pan={x:0,y:0};zoom=1;draw();if(layer==='gracia'){region='keucereus-alliance-base';select.value=region;draw();popup.classList.remove('atlas-movement-panel');popup.hidden=false;popup.innerHTML=dialogHeading('Грация',{id:'atlas-popup-title'})+graciaOverviewHtml();bindScenePreviews(popup);popup.querySelector('[data-dismiss]').onclick=()=>popup.hidden=true;}else popup.hidden=true;};root.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{zoom=Math.max(.5,Math.min(6,zoom*(b.dataset.zoom==='1'?1.4:1/1.4)));draw();});root.querySelector('[data-me]').onclick=()=>{focusMe();if(state.player.worldPoint){mode='city';pan={x:0,y:0};}draw();};root.querySelector('[data-interior-objects]').onclick=interiorObjects;root.querySelector('[data-movement]').onclick=()=>quickMenu();
    enhanceSelects(root);const resize=new ResizeObserver(draw);resize.observe(canvas);
    poller=createPoller(async({signal,current})=>{await bossPoll(signal,current);const next=await api('/api/world?live=1',{signal});if(!current()||busy||closed)return;const wasNative=Boolean(state.player.worldPoint);state={...state,...next.world,holdings:state.holdings.map(h=>({...h,...next.world.holdings.find(n=>n.id===h.id)}))};receivedAt=Date.now();if(await nativeArrival(wasNative,current))return;if(wasNative&&state.player.mode==='city')focusMe();if(followingNpc&&state.player.mode==='city'){if(region!==state.player.city){region=state.player.city;select.value=region;mode='city';pan={x:0,y:0};zoom=1;}if(!state.player.path?.length&&!state.player.pending)followingNpc=null;}if(approachAfterReturn&&state.player.mode!=='city'&&!state.player.channel)approachAfterReturn=null;if(approachAfterReturn&&state.player.mode==='city'){const npc=approachAfterReturn;approachAfterReturn=null;region=state.player.city;select.value=region;mode='city';pan={x:0,y:0};zoom=1;await act({action:'approach_npc',npc});}draw();},{interval:2000,enabled:()=>!closed&&!busy&&!document.querySelector('.hunt-overlay')});
    const shortcut=event=>{if(event.altKey&&event.code==='KeyB'&&!document.querySelector('.hunt-overlay')){event.preventDefault();quickMenu();}};document.addEventListener('keydown',shortcut);
    const close=()=>{playMusic('ambient');document.removeEventListener('keydown',shortcut);closed=true;poller.stop();cancelAnimationFrame(frame);resize.disconnect();images.clear();root.remove();};root.querySelector('[data-close]').onclick=close;root.querySelector('.overlay-backdrop').onclick=close;
    async function bossPoll(signal,current=()=>!closed){if(Date.now()-lastBossPoll<10000)return;lastBossPoll=Date.now();const next=await api('/api/boss/epic',{signal});if(current()){bosses=next.bosses||[];state.bosses=bosses;draw();}}function needsAnimation(){if(state.player.worldPoint)return !matchMedia('(prefers-reduced-motion: reduce)').matches&&state.player.runSpeed>0&&state.player.worldPath?.length;return state.player.path?.length||state.player.channel||state.player.mode==='siege'||state.player.mode==='road';}function ensureAnimation(){if(!frame&&!closed&&!document.hidden&&needsAnimation())frame=requestAnimationFrame(animate);}function animate(at){frame=0;if(closed||document.hidden)return;if(needsAnimation()&&at-lastFrame>100){lastFrame=at;draw();}ensureAnimation();}draw();if(options.initialHoldingId){const h=state.holdings.find(h=>h.id===options.initialHoldingId);if(h){region=h.region;select.value=region;mode='region';zoom=1;const city=state.cities.find(c=>c.id===region);pan={x:-(h.x-city.x)*canvas.clientWidth/100000,y:-(h.y-city.y)*canvas.clientWidth/100000};openMarker({kind:'holding',data:h});}}bossPoll().catch(()=>{});
